function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};

  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;

  return [];
}

const rawRisks = rowsOf('06 - Get Risks');

if (!rawRisks.length) {
  throw new Error('Không có dữ liệu rủi ro từ node 06.');
}

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function getCompetitor(risk) {
  const text = normalizeText(
    `${risk.title ?? ''} ${risk.reason ?? ''}`
  );

  const evidence = [
    ...(Array.isArray(risk.evidence) ? risk.evidence : []),
    ...(Array.isArray(risk.evidence_ids) ? risk.evidence_ids : [])
  ].map(String).join(' ');

  const combinedText = normalizeText(`${text} ${evidence}`);

  if (/\bted\b/.test(combinedText)) return 'TED';

  if (
    combinedText.includes('marques brownlee') ||
    /\bmkbhd\b/.test(combinedText)
  ) {
    return 'Marques Brownlee';
  }

  return 'Chưa xác định';
}

function getRiskType(risk) {
  const title = normalizeText(risk.title);
  const reason = normalizeText(risk.reason);
  const text = `${title} ${reason}`;

  if (
    /(\d+ video|video moi|tan suat dang|san luong noi dung|luong noi dung)/.test(text)
  ) {
    return 'Sản lượng nội dung';
  }

  if (
    title.includes('chu de') ||
    reason.includes('chu de noi dung') ||
    reason.includes('the thao va the thuc')
  ) {
    return 'Chủ đề nội dung';
  }

  if (
    text.includes('tuong tac') ||
    text.includes('luot xem') ||
    text.includes('binh luan') ||
    text.includes('luot thich')
  ) {
    return 'Hiệu suất tương tác';
  }

  return 'Rủi ro khác';
}

const groups = new Map();

for (const item of rawRisks) {
  const r = item.json ?? item;

  const risk = {
    risk_id: r.id,
    title: r.title ?? 'Chưa xác định',
    severity: String(r.severity ?? 'MEDIUM').toUpperCase(),
    reason: r.reason ?? 'Chưa có thông tin',
    evidence: Array.isArray(r.evidence)
      ? r.evidence
      : Array.isArray(r.evidence_ids)
        ? r.evidence_ids
        : []
  };

  const competitor = getCompetitor(risk);
  const riskType = getRiskType(risk);
  const key = `${competitor}|${riskType}`;

  if (!groups.has(key)) {
    groups.set(key, {
      competitor,
      risk_type: riskType,
      severity: 'LOW',
      reasons: [],
      evidence: [],
      source_risk_ids: []
    });
  }

  const group = groups.get(key);

  group.reasons.push(risk.reason);
  group.evidence.push(...risk.evidence);

  if (risk.risk_id != null) {
    group.source_risk_ids.push(risk.risk_id);
  }

  if (risk.severity === 'HIGH') {
    group.severity = 'HIGH';
  } else if (
    risk.severity === 'MEDIUM' &&
    group.severity !== 'HIGH'
  ) {
    group.severity = 'MEDIUM';
  }
}

const risks = [...groups.values()].map((group, index) => ({
  risk_id: index + 1,
  competitor: group.competitor,
  risk_type: group.risk_type,
  severity: group.severity,
  summary: [...new Set(group.reasons)],
  source_risk_ids: [...new Set(group.source_risk_ids)],
  evidence: [...new Set(group.evidence.map(String))],
  is_test_data: group.evidence.some(
    id => /TEST|MOCK/i.test(String(id))
  )
}));

// Tạo danh sách bằng chứng hợp lệ từ dữ liệu đầu vào.
const evidenceIds = [
  ...new Set(risks.flatMap(r => r.evidence))
];

if (!evidenceIds.length) {
  throw new Error('Không có mã bằng chứng để xây dựng chiến lược.');
}

const ai_prompt = `
Bạn là chuyên gia phân tích chiến lược nội dung YouTube.

Hãy đề xuất tối đa 3 chiến lược dựa trên dữ liệu rủi ro được cung cấp.

DỮ LIỆU RỦI RO:
${JSON.stringify(risks, null, 2)}

DANH SÁCH MÃ BẰNG CHỨNG ĐƯỢC PHÉP:
${JSON.stringify(evidenceIds, null, 2)}

QUY TẮC BẮT BUỘC:
- Viết bằng tiếng Việt.
- Dữ liệu TEST/MOCK chỉ dùng để thử nghiệm, không phải bằng chứng thực tế.
- Chỉ sử dụng mã bằng chứng có trong danh sách được phép.
- Mỗi chiến lược phải có ít nhất 1 mã bằng chứng liên quan trực tiếp trong trường evidence.
- Trường evidence phải là mảng các chuỗi mã bằng chứng, không được để mảng rỗng.
- Không gán mã bằng chứng chỉ vì mã đó xuất hiện trong dữ liệu; phải kiểm tra sự liên quan với chiến lược.
- Không tự tạo số liệu, sự kiện hoặc mã bằng chứng.
- Mọi chiến lược phải tập trung vào việc cải thiện kênh YouTube của chính chúng ta, không phải thay đổi đối thủ.
- Không giả định chúng ta có cùng chủ đề, khán giả hoặc nguồn lực với đối thủ.
- Nếu chưa có dữ liệu khán giả, hãy nêu rõ giới hạn này.
- Đề xuất tối đa 3 chiến lược với hướng hành động khác nhau.
- Mô tả cách triển khai, chỉ số đo lường và giới hạn của dữ liệu.
- Confidence phải nằm trong khoảng 0 đến 1.
- Priority chỉ được là LOW, MEDIUM hoặc HIGH.
- Không khẳng định chiến lược chắc chắn thành công.
- Không khẳng định doanh thu hoặc thứ hạng tìm kiếm sẽ tăng nếu chưa có bằng chứng.
- Chỉ trả về JSON hợp lệ, không có Markdown.

CẤU TRÚC JSON:
{
  "strategies": [
    {
      "title": "Tên chiến lược",
      "objective": "Mục tiêu",
      "description": "Hành động triển khai và chỉ số đo lường",
      "priority": "MEDIUM",
      "confidence": 0.3,
      "evidence": ["Mã bằng chứng có thật từ danh sách được phép"],
      "target_audience": "Đối tượng mục tiêu hoặc giới hạn dữ liệu",
      "content_format": "Định dạng nội dung",
      "focus_topic": "Chủ đề tập trung",
      "reason": "Lý do và căn cứ lựa chọn",
      "expected_impact": "Tác động dự kiến và giới hạn bằng chứng"
    }
  ]
}

Kiểm tra trước khi trả kết quả:
1. Mọi mã trong evidence phải nằm trong danh sách được phép.
2. Mỗi chiến lược phải có evidence không rỗng.
3. Các chiến lược phải có hướng hành động khác nhau.
4. Không đưa mã bằng chứng vào target_audience.
5. Không coi dữ liệu TEST/MOCK là kết quả thực tế.
`;

return [{
  json: {
    risk_count: risks.length,
    risks,
    evidence: evidenceIds,
    ai_prompt
  }
}];

const out = [];

const requiredFields = [
  'title',
  'objective',
  'description',
  'target_audience',
  'content_format',
  'focus_topic',
  'reason',
  'expected_impact'
];

for (const item of $input.all()) {
  const d = item.json;
  const errors = [];

  // 1. Kiểm tra trường bắt buộc
  for (const field of requiredFields) {
    if (
      typeof d[field] !== 'string' ||
      d[field].trim() === ''
    ) {
      errors.push(`${field} is required`);
    }
  }

  // 2. Kiểm tra mức độ ưu tiên
  if (!['HIGH', 'MEDIUM', 'LOW'].includes(d.priority)) {
    errors.push('priority must be HIGH, MEDIUM or LOW');
  }

  // 3. Kiểm tra confidence
  if (
    typeof d.confidence !== 'number' ||
    !Number.isFinite(d.confidence) ||
    d.confidence < 0 ||
    d.confidence > 1
  ) {
    errors.push('confidence must be between 0 and 1');
  }

  // 4. Kiểm tra bằng chứng
  if (!Array.isArray(d.evidence) || d.evidence.length === 0) {
    errors.push('evidence must be a non-empty array');
  } else if (
    !d.evidence.every(
      e => typeof e === 'string' && e.trim() !== ''
    )
  ) {
    errors.push('evidence contains invalid entries');
  }

  // 5. Không chấp nhận mục tiêu kiểm soát đối thủ
  const strategyText = [
  d.objective,
  d.description,
  d.reason,
  d.expected_impact
].join(' ').toLowerCase();

const prohibitedPatterns = [
  /giảm\s+(?:lượng\s+)?nội dung\s+(?:tăng nhanh\s+)?của\s+đối thủ/,
  /giảm\s+lượt xem\s+của\s+đối thủ/,
  /giảm\s+sự chú ý\s+đến\s+đối thủ/,
  /giảm\s+tương tác\s+của\s+đối thủ/
];

if (prohibitedPatterns.some(pattern => pattern.test(strategyText))) {
  errors.push('Strategy must focus on improving our own channel');
}

  // 6. Đánh dấu bằng chứng thử nghiệm
  const isTestEvidence = Array.isArray(d.evidence) &&
  d.evidence.some(e => /TEST|MOCK/i.test(e));

  out.push({
    json: {
      ...d,
      is_test_evidence: isTestEvidence,
      is_valid: errors.length === 0,
      validation_errors: errors
    }
  });
}

return out;

return $input.all().map(item => {
  const d = item.json;

  const evidence = Array.isArray(d.evidence)
    ? d.evidence
    : [];

  // Phân loại mã bằng chứng thử nghiệm
  const testEvidence = evidence.filter(id =>
    /^(TEST|MOCK)(_|$)/i.test(String(id))
  );

  const realEvidence = evidence.filter(id =>
    !/^(TEST|MOCK)(_|$)/i.test(String(id))
  );

  // Chỉ số lượng bằng chứng không đủ để xác định độ tin cậy.
  // Tạm thời giảm độ tin cậy nếu dữ liệu chỉ là dữ liệu thử nghiệm.
  const aiConfidence = Number(d.confidence);

  let confidence = Number.isFinite(aiConfidence)
    ? Math.max(0, Math.min(1, aiConfidence))
    : 0.3;

  if (evidence.length === 0) {
    confidence = Math.min(confidence, 0.2);
  } else if (realEvidence.length === 0) {
    confidence = Math.min(confidence, 0.3);
  } else if (testEvidence.length > 0) {
    confidence = Math.min(confidence, 0.5);
  }

  return {
    json: {
      ...d,
      confidence: Number(confidence.toFixed(2)),
      evidence_quality: evidence.length === 0
        ? 'NO_EVIDENCE'
        : realEvidence.length === 0
          ? 'TEST_DATA_ONLY'
          : testEvidence.length > 0
            ? 'MIXED_DATA'
            : 'UNVERIFIED_DATA',
      test_evidence_count: testEvidence.length,
      other_evidence_count: realEvidence.length,
      created_at: new Date().toISOString()
    }
  };
});

const inputs = $input.all();

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function extractContent(item) {
  const r = item.json ?? {};

  let content =
    r.content ??
    r.message?.content ??
    r.output?.[0]?.content?.[0]?.text ??
    r.text ??
    '';

  // Nếu content đã là object thì không cần parse chuỗi bên ngoài.
  if (typeof content === 'object' && content !== null) {
    return content;
  }

  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Node 09 không trả về nội dung AI hợp lệ.');
  }

  content = content
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();

  try {
    return JSON.parse(content);
  } catch (error) {
    throw new Error(
      'JSON từ AI không hợp lệ hoặc bị cắt. ' +
      'Kiểm tra OUTPUT đầy đủ của node 09. Chi tiết: ' +
      error.message +
      '. Nội dung đầu: ' +
      content.slice(0, 200)
    );
  }
}

const priorities = ['HIGH', 'MEDIUM', 'LOW'];
const strategies = [];

for (const item of inputs) {
  let parsed = extractContent(item);

  // Xử lý thêm trường hợp JSON bị bọc trong một chuỗi JSON khác.
  for (let i = 0; i < 2 && typeof parsed === 'string'; i++) {
    try {
      parsed = JSON.parse(parsed);
    } catch {
      break;
    }
  }

  let list;

  if (Array.isArray(parsed)) {
    list = parsed;
  } else if (Array.isArray(parsed.strategies)) {
    list = parsed.strategies;
  } else if (
    parsed.title ||
    parsed.objective ||
    parsed.description
  ) {
    list = [parsed];
  } else {
    throw new Error(
      'Không tìm thấy strategies hoặc đối tượng chiến lược trong JSON AI.'
    );
  }

  for (const s of list) {
    if (!s || typeof s !== 'object') continue;

    const title = String(s.title ?? '').trim();
    if (!title) continue;

    const confidence = Number(s.confidence);
    const rawPriority = String(s.priority ?? '').toUpperCase();

    strategies.push({
      title,
      objective: String(s.objective ?? '').trim(),
      description: String(s.description ?? '').trim(),

      priority: priorities.includes(rawPriority)
        ? rawPriority
        : 'MEDIUM',

      confidence: Number.isFinite(confidence)
        ? Math.max(0, Math.min(1, confidence))
        : 0.3,

      evidence: Array.isArray(s.evidence)
        ? [...new Set(
            s.evidence
              .filter(v => typeof v === 'string' && v.trim())
              .map(v => v.trim())
          )]
        : [],

      target_audience: String(s.target_audience ?? '').trim(),
      content_format: String(s.content_format ?? '').trim(),
      focus_topic: String(s.focus_topic ?? '').trim(),
      reason: String(s.reason ?? '').trim(),
      expected_impact: String(s.expected_impact ?? '').trim()
    });
  }
}

// Loại tiêu đề trùng nhau.
const seen = new Set();
const output = [];

for (const strategy of strategies) {
  const key = normalizeText(strategy.title);

  if (!key || seen.has(key)) continue;

  seen.add(key);
  output.push({ json: strategy });
}

if (output.length === 0) {
  throw new Error('AI không trả về chiến lược hợp lệ.');
}

return output;
